        score -= (post_residual - bin_capacity / 4) as f64 * 2.5;
    }

    // Reward high bin capacities utilization
    if bin_capacity - post_residual < bin_capacity / 2 {
        score += ((bin_capacity - post_residual) as f64 / bin_capacity as f64).powi(3) * 1.5;
    } else {
        score -= ((bin_capacity - post_residual) as f64 / bin_capacity as f64).powi(3) * 2.0;
    }

    // Penalize if next item size is large relative to post_residual
