        score += ((fitting_bins_count - 2) as f64).powi(2) * 1.3;
    }

    // Penalize for low open bins count
    if open_bins_count < total_items / 4 {
        score -= (open_bins_count as f64 / total_items as f64).powi(2) * 2.0;
    }

    // Reward for high mean residual utilization
    if post_residual > mean_residual {
        score += ((post_residual - mean_residual) as f64 / mean_residual).powi(2) * 1.2;
    } else {
        score -= ((mean_residual - post_residual) as f64 / mean_residual).powi(2) * 3.0;
    }

    // Penalize for small bin residual
    if bin_residual < 15 {
        score -= (15 - bin_residual) as f64 * 2.0;
    }

    // Apply a penalty if post_residual is close to bin_capacity
    if post_residual > bin_capacity - item_size - 20 {
        score -= (post_residual - (bin_capacity - item_size - 20)) as f64 * 1.5;
    } else {
        score += (bin_capacity - post_residual) as f64 / 10.0 * 1.1;
    }

    // Reward for high stream progress
    if step_index > total_items / 2 {
        score += ((step_index as f64 / total_items as f64).powi(3)) * 0.5;
    } else {
        score -= ((total_items as f64 / step_index as f64).powi(3)) * 0.7;
    }

    score
}

